1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.Clock;
6	import java.time.LocalDate;
7	import java.time.LocalDateTime;
8	import java.util.ArrayList;
9	import java.util.Comparator;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.TreeMap;
13	
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	
17	import com.example.starter.api.dto.CommandActionRequest;
18	import com.example.starter.api.dto.CommandResponse;
19	import com.example.starter.api.dto.DailySummaryResponse;
20	import com.example.starter.api.dto.ExecutePlanRequest;
21	import com.example.starter.api.dto.PlanResultResponse;
22	import com.example.starter.api.dto.PlanStatusResponse;
23	import com.example.starter.api.dto.PlanSubmitRequest;
24	import com.example.starter.api.dto.ReadingAckResponse;
25	import com.example.starter.api.dto.ReadingBatchRequest;
26	import com.example.starter.api.dto.ReadingItem;
27	import com.example.starter.api.dto.SealRequest;
28	import com.example.starter.api.dto.SwitchPlanRequest;
29	import com.example.starter.config.ApplicationClock;
30	import com.example.starter.config.CementProperties;
31	import com.example.starter.domain.BusinessException;
32	import com.example.starter.domain.CoFiringPlan;
33	import com.example.starter.domain.CommandStatus;
34	import com.example.starter.domain.EmissionReading;
35	import com.example.starter.domain.HazardousWasteLicense;
36	import com.example.starter.domain.HourlyAssessment;
37	import com.example.starter.domain.PlanFuel;
38	import com.example.starter.domain.PlanStatus;
39	import com.example.starter.domain.RejectCategory;
40	import com.example.starter.domain.ReductionCommand;
41	import com.example.starter.repo.BanRepository;
42	import com.example.starter.repo.CommandRepository;
43	import com.example.starter.repo.DailySummaryRepository;
44	import com.example.starter.repo.FuelRepository;
45	import com.example.starter.repo.HourlyAssessmentRepository;
46	import com.example.starter.repo.IdempotentRepository;
47	import com.example.starter.repo.KilnLockRepository;
48	import com.example.starter.repo.LicenseRepository;
49	import com.example.starter.repo.PlanRepository;
50	import com.example.starter.repo.ReadingRepository;
51	import com.fasterxml.jackson.databind.ObjectMapper;
52	
53	/**
54	 * 水泥窑替代燃料掺烧与排放联动核心服务。
55	 *
56	 * <p>状态流转：申报→（同步合成审核）→审核通过/整单拒绝→执行→小时评估→日结封存。
57	 * 所有边界判定均为“恰等于合法/达标/触发”：替代率恰 40% 合法、均值恰限值达标、
58	 * 下发恰满 30 分钟升级、恰连续 3 次超标禁烧。</p>
59	 */
60	@Service
61	public class CementService {
62	
63	    private static final int RATE_SCALE = 4;
64	    private static final int MASS_SCALE = 3;
65	    private static final int AVG_SCALE = 3;
66	
67	    private final PlanRepository planRepository;
68	    private final FuelRepository fuelRepository;
69	    private final LicenseRepository licenseRepository;
70	    private final KilnLockRepository kilnLockRepository;
71	    private final ReadingRepository readingRepository;
72	    private final HourlyAssessmentRepository hourlyAssessmentRepository;
73	    private final CommandRepository commandRepository;
74	    private final IdempotentRepository idempotentRepository;
75	    private final BanRepository banRepository;
76	    private final DailySummaryRepository dailySummaryRepository;
77	    private final CementProperties properties;
78	    private final ApplicationClock clock;
79	    private final ObjectMapper objectMapper;
80	
81	    public CementService(PlanRepository planRepository, FuelRepository fuelRepository,
82	                         LicenseRepository licenseRepository, KilnLockRepository kilnLockRepository,
83	                         ReadingRepository readingRepository,
84	                         HourlyAssessmentRepository hourlyAssessmentRepository,
85	                         CommandRepository commandRepository,
86	                         IdempotentRepository idempotentRepository,
87	                         BanRepository banRepository,
88	                         DailySummaryRepository dailySummaryRepository,
89	                         CementProperties properties,
90	                         Clock clock,
91	                         ObjectMapper objectMapper) {
92	        this.planRepository = planRepository;
93	        this.fuelRepository = fuelRepository;
94	        this.licenseRepository = licenseRepository;
95	        this.kilnLockRepository = kilnLockRepository;
96	        this.readingRepository = readingRepository;
97	        this.hourlyAssessmentRepository = hourlyAssessmentRepository;
98	        this.commandRepository = commandRepository;
99	        this.idempotentRepository = idempotentRepository;
100	        this.banRepository = banRepository;
101	        this.dailySummaryRepository = dailySummaryRepository;
102	        this.properties = properties;
103	        this.clock = (ApplicationClock) clock;
104	        this.objectMapper = objectMapper;
105	    }
106	
107	    // ---------------------------------------------------------------------
108	    // 申报与审核
109	    // ---------------------------------------------------------------------
110	
111	    /**
112	     * 方案申报并同步完成合成审核。以 requestId 幂等：同键同参返回首次结果，同键异参 409。
113	     * 整单拒绝条件（按顺序）：替代率超 40%、许可缺失/过期、高氯硫加权氯/硫超限、窑被占用。
114	     */
115	    @Transactional
116	    public PlanResultResponse submit(PlanSubmitRequest request) {
117	        String fingerprint = FingerprintUtil.sha256(objectMapper, request.requestId(), request);
118	        var existing = idempotentRepository.find(request.requestId());
119	        if (existing != null) {
120	            if (!existing.fingerprint().equals(fingerprint)) {
121	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
122	                        "requestId=" + request.requestId() + " 已用于不同业务参数的申报，拒绝重复受理");
123	            }
124	            return readJson(existing.responseBody(), PlanResultResponse.class);
125	        }
126	
127	        LocalDateTime now = LocalDateTime.now(clock);
128	        // 同窑申报串行化，保证“并发申报唯一受理”
129	        kilnLockRepository.lockKiln(request.kilnId());
130	        // 获锁后重检：排队期间首个事务可能已提交同 requestId 结果
131	        var committed = idempotentRepository.find(request.requestId());
132	        if (committed != null) {
133	            if (!committed.fingerprint().equals(fingerprint)) {
134	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
135	                        "requestId=" + request.requestId() + " 已用于不同业务参数的申报，拒绝重复受理");
136	            }
137	            return readJson(committed.responseBody(), PlanResultResponse.class);
138	        }
139	
140	        BigDecimal chlorineTotal = BigDecimal.ZERO.setScale(MASS_SCALE, RoundingMode.HALF_UP);
141	        BigDecimal sulfurTotal = BigDecimal.ZERO.setScale(MASS_SCALE, RoundingMode.HALF_UP);
142	        for (var fuel : request.fuels()) {
143	            if (Boolean.TRUE.equals(fuel.highClSulfur())) {
144	                chlorineTotal = chlorineTotal.add(
145	                        fuel.massKg().multiply(fuel.chlorinePct()).movePointLeft(2));
146	                sulfurTotal = sulfurTotal.add(
147	                        fuel.massKg().multiply(fuel.sulfurPct()).movePointLeft(2));
148	            }
149	        }
150	        chlorineTotal = chlorineTotal.setScale(MASS_SCALE, RoundingMode.HALF_UP);
151	        sulfurTotal = sulfurTotal.setScale(MASS_SCALE, RoundingMode.HALF_UP);
152	
153	        RejectCategory category = null;
154	        String reason = null;
155	        HazardousWasteLicense license = licenseRepository.findByLicenseNo(request.licenseNo());
156	        LocalDate today = LocalDate.now(clock);
157	
158	        if (request.substitutionRate().compareTo(properties.getMaxSubstitutionRate()) > 0) {
159	            category = RejectCategory.RATE_EXCEEDED;
160	            reason = "替代燃料热量替代率 " + ratePercent(request.substitutionRate())
161	                    + "% 超过上限 " + ratePercent(properties.getMaxSubstitutionRate()) + "%，整单拒绝";
162	        } else if (license == null) {
163	            category = RejectCategory.LICENSE_INVALID;
164	            reason = "危废经营许可证号 " + request.licenseNo() + " 不存在，整单拒绝";
165	        } else if (license.validTo().isBefore(today)) {
166	            category = RejectCategory.LICENSE_INVALID;
167	            reason = "危废经营许可 " + license.licenseNo() + " 已于 " + license.validTo()
168	                    + " 过期，整单拒绝";
169	        } else if (chlorineTotal.compareTo(properties.getChlorineLimitKg()) > 0) {
170	            category = RejectCategory.CHLORINE_EXCEEDED;
171	            reason = "高氯硫燃料加权入窑氯总量 " + chlorineTotal + "kg 超过限值 "
172	                    + properties.getChlorineLimitKg() + "kg，整单拒绝";
173	        } else if (sulfurTotal.compareTo(properties.getSulfurLimitKg()) > 0) {
174	            category = RejectCategory.SULFUR_EXCEEDED;
175	            reason = "高氯硫燃料加权入窑硫总量 " + sulfurTotal + "kg 超过限值 "
176	                    + properties.getSulfurLimitKg() + "kg，整单拒绝";
177	        } else if (planRepository.findBlocking(request.kilnId(),
178	                request.plannedStart(), request.plannedEnd()) != null) {
179	            category = RejectCategory.KILN_OCCUPIED;
180	            reason = "窑 " + request.kilnId() + " 在 " + request.plannedStart() + "~"
181	                    + request.plannedEnd() + " 已存在审核通过/执行中方案，并发申报仅唯一受理";
182	        }
183	
184	        PlanStatus status = category == null ? PlanStatus.APPROVED : PlanStatus.REJECTED;
185	        String planNo = generatePlanNo(now);
186	        CoFiringPlan plan = new CoFiringPlan(
187	                null, request.requestId(), planNo, request.kilnId(),
188	                license == null ? null : license.id(),
189	                request.substitutionRate().setScale(RATE_SCALE, RoundingMode.HALF_UP),
190	                status, request.plannedStart(), request.plannedEnd(),
191	                reason, category == null ? null : category.name(),
192	                now, now, null, null, null, null, null);
193	        long planId = planRepository.insert(plan);
194	        // 无论通过或拒绝均保留燃料快照，支撑氯硫加权复算
195	        fuelRepository.insertBatch(planId, request.fuels());
196	
197	        CoFiringPlan saved = planRepository.findById(planId);
198	        PlanResultResponse response = toPlanResult(saved, chlorineTotal, sulfurTotal);
199	        idempotentRepository.trySave(request.requestId(), "PLAN_SUBMIT", fingerprint,
200	                200, writeJson(response), planId);
201	        return response;
202	    }
203	
204	    // ---------------------------------------------------------------------
205	    // 执行 / 切换 / 停用
206	    // ---------------------------------------------------------------------
207	
208	    /** 启动审核通过的方案；同窑同时刻只允许一个执行中方案，当日禁烧则拒绝。 */
209	    @Transactional
210	    public PlanStatusResponse execute(ExecutePlanRequest request) {
211	        CoFiringPlan plan = requirePlanByNo(request.planNo());
212	        LocalDateTime now = LocalDateTime.now(clock);
213	        return startPlan(plan, now);
214	    }
215	
216	    private PlanStatusResponse startPlan(CoFiringPlan plan, LocalDateTime now) {
217	        if (plan.status() != PlanStatus.APPROVED) {
218	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
219	                    "方案 " + plan.planNo() + " 当前状态 " + plan.status() + "，仅审核通过方案可启动执行");
220	        }
221	        if (banRepository.exists(plan.kilnId(), now.toLocalDate())) {
222	            throw BusinessException.unprocessable(RejectCategory.KILN_BANNED,
223	                    "窑 " + plan.kilnId() + " 当日已因连续3小时超标禁烧，禁止启动掺烧");
224	        }
225	        if (!kilnLockRepository.tryAcquire(plan.kilnId(), plan.id(), now)) {
226	            throw BusinessException.conflict(RejectCategory.KILN_OCCUPIED,
227	                    "窑 " + plan.kilnId() + " 同时刻已有执行中方案，方案 " + plan.planNo() + " 不予受理");
228	        }
229	        int updated = planRepository.markStarted(plan.id(), now);
230	        if (updated == 0) {
231	            kilnLockRepository.release(plan.kilnId());
232	            throw BusinessException.conflict(RejectCategory.KILN_OCCUPIED,
233	                    "方案 " + plan.planNo() + " 启动时状态已变化，受理失败");
234	        }
235	        return toStatusResponse(planRepository.findById(plan.id()));
236	    }
237	
238	    /** 方案切换：先停旧后启新，两步在同一事务内完成。以 requestId 幂等。 */
239	    @Transactional
240	    public PlanStatusResponse switchPlan(SwitchPlanRequest request) {
241	        String fingerprint = FingerprintUtil.sha256(objectMapper, request.requestId(), request);
242	        var existing = idempotentRepository.find(request.requestId());
243	        if (existing != null) {
244	            if (!existing.fingerprint().equals(fingerprint)) {
245	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
246	                        "requestId=" + request.requestId() + " 已用于不同切换参数，拒绝执行");
247	            }
248	            return readJson(existing.responseBody(), PlanStatusResponse.class);
249	        }
250	
251	        kilnLockRepository.lockKiln(request.kilnId());
252	        CoFiringPlan oldPlan = planRepository.findActiveByKiln(request.kilnId());
253	        if (oldPlan == null) {
254	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
255	                    "窑 " + request.kilnId() + " 当前无执行中方案，无需切换");
256	        }
257	        CoFiringPlan newPlan = requirePlanByNo(request.newPlanNo());
258	        if (!newPlan.kilnId().equals(request.kilnId())) {
259	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
260	                    "新方案 " + newPlan.planNo() + " 不属于窑 " + request.kilnId());
261	        }
262	        if (newPlan.status() != PlanStatus.APPROVED) {
263	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
264	                    "新方案 " + newPlan.planNo() + " 当前状态 " + newPlan.status() + "，仅审核通过方案可切换启动");
265	        }
266	        if (banRepository.exists(request.kilnId(), LocalDate.now(clock))) {
267	            throw BusinessException.unprocessable(RejectCategory.KILN_BANNED,
268	                    "窑 " + request.kilnId() + " 当日已禁烧，禁止切换到新掺烧方案");
269	        }
270	        LocalDateTime now = LocalDateTime.now(clock);
271	
272	        // 先停旧：状态机条件更新
273	        int stopped = planRepository.markStopped(oldPlan.id(), now);
274	        if (stopped == 0) {
275	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
276	                    "旧方案 " + oldPlan.planNo() + " 停用失败，状态已变化");
277	        }
278	        // 后启新：同事务直接把窑占用行改挂新方案
279	        int started = planRepository.markStarted(newPlan.id(), now);
280	        if (started == 0) {
281	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
282	                    "新方案 " + newPlan.planNo() + " 启动失败，状态已变化");
283	        }
284	        if (kilnLockRepository.replace(request.kilnId(), newPlan.id(), now) == 0) {
285	            throw BusinessException.unprocessable(RejectCategory.KILN_OCCUPIED,
286	                    "窑占用槽缺失，切换失败");
287	        }
288	        PlanStatusResponse response = toStatusResponse(planRepository.findById(newPlan.id()));
289	        idempotentRepository.trySave(request.requestId(), "PLAN_SWITCH", fingerprint, 200,
290	                writeJson(response), newPlan.id());
291	        return response;
292	    }
293	
294	    /** 手动停用并释放窑。 */
295	    @Transactional
296	    public PlanStatusResponse stop(String planNo) {
297	        CoFiringPlan plan = requirePlanByNo(planNo);
298	        LocalDateTime now = LocalDateTime.now(clock);
299	        int updated = planRepository.markStopped(plan.id(), now);
300	        if (updated == 0) {
301	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
302	                    "方案 " + planNo + " 当前状态 " + plan.status() + "，不可停用");
303	        }
304	        kilnLockRepository.release(plan.kilnId());
305	        return toStatusResponse(planRepository.findById(plan.id()));
306	    }
307	
308	    // ---------------------------------------------------------------------
309	    // 读数上报与小时评估
310	    // ---------------------------------------------------------------------
311	
312	    /**
313	     * 排放读数批量上报：按“测点＋采样时刻”去重，乱序数据按采样时刻归位评估。
314	     * 方案封存（SEALED）后到达的读数只登记迟到事件。
315	     */
316	    @Transactional
317	    public ReadingAckResponse ingestReadings(ReadingBatchRequest request) {
318	        CoFiringPlan plan = requirePlanByNo(request.planNo());
319	        boolean sealed = plan.status() == PlanStatus.SEALED;
320	        int inserted = 0;
321	        int duplicated = 0;
322	        int late = 0;
323	
324	        List<ReadingItem> accepted = new ArrayList<>();
325	        for (ReadingItem item : request.readings()) {
326	            if (sealed) {
327	                readingRepository.insertLateEvent(plan.id(), item, writeJson(item));
328	                late++;
329	                continue;
330	            }
331	            boolean ok = readingRepository.tryInsert(plan.id(), plan.kilnId(), item, false);
332	            if (ok) {
333	                inserted++;
334	                accepted.add(item);
335	            } else {
336	                duplicated++;
337	            }
338	        }
339	
340	        if (!sealed && inserted > 0) {
341	            // 乱序归位：重算受影响日期内所有小时评估
342	            LocalDate minDate = accepted.stream().map(i -> i.sampleTime().toLocalDate())
343	                    .min(Comparator.naturalOrder()).orElse(LocalDate.now(clock));
344	            LocalDate maxDate = accepted.stream().map(i -> i.sampleTime().toLocalDate())
345	                    .max(Comparator.naturalOrder()).orElse(minDate);
346	            for (LocalDate d = minDate; !d.isAfter(maxDate); d = d.plusDays(1)) {
347	                evaluateDay(plan, d);
348	            }
349	        }
350	        return new ReadingAckResponse(request.readings().size(), inserted, duplicated, late);
351	    }
352	
353	    /**
354	     * 重算指定日期各小时均值：按小时分桶、跨测点算术平均（仅统计非空污染物）；
355	     * 均值严格大于限值判超标（恰等于达标）。连续超标序号按小时序累计，恰连续 3 次禁烧。
356	     */
357	    private void evaluateDay(CoFiringPlan plan, LocalDate date) {
358	        List<EmissionReading> readings = readingRepository.findByPlanAndDate(plan.id(), date);
359	        Map<LocalDateTime, List<EmissionReading>> buckets = new TreeMap<>();
360	        for (EmissionReading r : readings) {
361	            LocalDateTime hour = r.sampleTime().withMinute(0).withSecond(0).withNano(0);
362	            buckets.computeIfAbsent(hour, k -> new ArrayList<>()).add(r);
363	        }
364	
365	        // 按采样时刻归位后顺序重算当日各小时，连续超标序号在内存中累计（跨日重置为0）
366	        int runningConsecutive = 0;
367	        for (Map.Entry<LocalDateTime, List<EmissionReading>> e : buckets.entrySet()) {
368	            LocalDateTime hour = e.getKey();
369	            List<EmissionReading> list = e.getValue();
370	            BigDecimal noxAvg = average(list, EmissionReading::nox);
371	            BigDecimal so2Avg = average(list, EmissionReading::so2);
372	            BigDecimal dustAvg = average(list, EmissionReading::dust);
373	
374	            List<String> exceededPollutants = new ArrayList<>();
375	            BigDecimal worstAvg = null;
376	            if (noxAvg != null && exceeds(noxAvg, "NOX")) {
377	                exceededPollutants.add("NOX");
378	                worstAvg = max(worstAvg, noxAvg);
379	            }
380	            if (so2Avg != null && exceeds(so2Avg, "SO2")) {
381	                exceededPollutants.add("SO2");
382	                worstAvg = max(worstAvg, so2Avg);
383	            }
384	            if (dustAvg != null && exceeds(dustAvg, "DUST")) {
385	                exceededPollutants.add("DUST");
386	                worstAvg = max(worstAvg, dustAvg);
387	            }
388	            boolean exceeded = !exceededPollutants.isEmpty();
389	            String pollutants = String.join(",", exceededPollutants);
390	            runningConsecutive = exceeded ? runningConsecutive + 1 : 0;
391	            int consecutive = runningConsecutive;
392	
393	            hourlyAssessmentRepository.upsert(new HourlyAssessment(
394	                    null, plan.id(), hour, noxAvg, so2Avg, dustAvg, list.size(),
395	                    exceeded, pollutants, consecutive));
396	
397	            if (exceeded) {
398	                // 触发降掺指令（每小时至多一单）
399	                BigDecimal target = properties.getFloorSubstitutionRate().setScale(RATE_SCALE,
400	                        RoundingMode.HALF_UP);
401	                commandRepository.insertIfAbsent(new ReductionCommand(
402	                        null, plan.id(), hour, pollutants, worstAvg,
403	                        CommandStatus.TRIGGERED, target, LocalDateTime.now(clock),
404	                        null, null, null, null));
405	            }
406	
407	            if (consecutive == properties.getConsecutiveExceedBan()
408	                    && planRepository.markBanned(plan.id(), LocalDateTime.now(clock)) > 0) {
409	                // 恰连续3次：当日禁烧；markBanned 条件更新保证只生效一次
410	                kilnLockRepository.release(plan.kilnId());
411	                banRepository.insert(plan.id(), plan.kilnId(), date,
412	                        "连续" + consecutive + "个小时均值超标，当日禁止掺烧");
413	            }
414	        }
415	    }
416	
417	    // ---------------------------------------------------------------------
418	    // 降掺指令链
419	    // ---------------------------------------------------------------------
420	
421	    /** 下发降掺指令（触发→下发）。以 requestId 幂等。 */
422	    @Transactional
423	    public CommandResponse issueCommand(CommandActionRequest request) {
424	        String fingerprint = FingerprintUtil.sha256(objectMapper, request.requestId(), request);
425	        var existing = idempotentRepository.find(request.requestId());
426	        if (existing != null) {
427	            if (!existing.requestType().equals("COMMAND_ISSUE")) {
428	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
429	                        "requestId=" + request.requestId() + " 已用于其他类型操作，拒绝下发");
430	            }
431	            if (!existing.fingerprint().equals(fingerprint)) {
432	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
433	                        "requestId=" + request.requestId() + " 已用于不同下发参数，拒绝执行");
434	            }
435	            return readJson(existing.responseBody(), CommandResponse.class);
436	        }
437	
438	        CoFiringPlan plan = requirePlanByNo(request.planNo());
439	        ReductionCommand command = resolveCommand(plan, request.hourStart(), true);
440	        LocalDateTime now = LocalDateTime.now(clock);
441	        if (command.status() == CommandStatus.TRIGGERED) {
442	            int updated = commandRepository.markIssued(command.id(), now);
443	            if (updated == 0) {
444	                throw BusinessException.conflict(RejectCategory.ILLEGAL_STATE,
445	                        "指令状态已变化，下发失败");
446	            }
447	            command = commandRepository.findByPlanAndHour(plan.id(), command.hourStart());
448	        }
449	        CommandResponse response = toCommandResponse(plan.planNo(), command);
450	        idempotentRepository.trySave(request.requestId(), "COMMAND_ISSUE", fingerprint, 200,
451	                writeJson(response), plan.id());
452	        return response;
453	    }
454	
455	    /** 执行确认（下发→确认）。以 requestId 幂等，且不改变已生效的执行参数。 */
456	    @Transactional
457	    public CommandResponse confirmCommand(CommandActionRequest request) {
458	        String fingerprint = FingerprintUtil.sha256(objectMapper, request.requestId(), request);
459	        var existing = idempotentRepository.find(request.requestId());
460	        if (existing != null) {
461	            if (!existing.requestType().equals("COMMAND_CONFIRM")) {
462	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
463	                        "requestId=" + request.requestId() + " 已用于其他类型操作，拒绝确认");
464	            }
465	            if (!existing.fingerprint().equals(fingerprint)) {
466	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
467	                        "requestId=" + request.requestId() + " 已用于不同确认参数，拒绝执行");
468	            }
469	            return readJson(existing.responseBody(), CommandResponse.class);
470	        }
471	
472	        CoFiringPlan plan = requirePlanByNo(request.planNo());
473	        ReductionCommand command = resolveCommand(plan, request.hourStart(), false);
474	        LocalDateTime now = LocalDateTime.now(clock);
475	        if (command.status() == CommandStatus.TRIGGERED) {
476	            throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
477	                    "指令尚未下发，不能执行确认");
478	        }
479	        if (command.status() == CommandStatus.ISSUED || command.status() == CommandStatus.ESCALATED) {
480	            int updated = commandRepository.markConfirmed(command.id(), request.requestId(), now);
481	            if (updated == 0) {
482	                throw BusinessException.unprocessable(RejectCategory.ILLEGAL_STATE,
483	                        "指令确认时状态已变化");
484	            }
485	            command = commandRepository.findByPlanAndHour(plan.id(), command.hourStart());
486	        }
487	        CommandResponse response = toCommandResponse(plan.planNo(), command);
488	        idempotentRepository.trySave(request.requestId(), "COMMAND_CONFIRM", fingerprint, 200,
489	                writeJson(response), plan.id());
490	        return response;
491	    }
492	
493	    /**
494	     * 扫描已下发指令：下发恰满 30 分钟（issued_at + 30min &lt;= now）仍未确认，
495	     * 自动升级 ESCALATED 并强制降至保底比例。
496	     */
497	    @Transactional
498	    public int scanCommandTimeouts() {
499	        LocalDateTime deadline = LocalDateTime.now(clock)
500	                .minusMinutes(properties.getCommandConfirmTimeoutMinutes());
501	        List<ReductionCommand> overdue = commandRepository.findIssuedOverdue(deadline);
502	        int escalated = 0;
503	        LocalDateTime now = LocalDateTime.now(clock);
504	        for (ReductionCommand cmd : overdue) {
505	            if (commandRepository.markEscalated(cmd.id(), now) > 0) {
506	                escalated++;
507	            }
508	        }
509	        return escalated;
510	    }
511	
512	    // ---------------------------------------------------------------------
513	    // 日结与封存
514	    // ---------------------------------------------------------------------
515	
516	    /** 查询日结（未封存实时复算；封存后返回封存快照）。 */
517	    @Transactional
518	    public DailySummaryResponse getDailySummary(String planNo, LocalDate date) {
519	        CoFiringPlan plan = requirePlanByNo(planNo);
520	        return buildSummary(plan, date);
521	    }
522	
523	    /** 日结封存：终态。重复封存返回幂等成功；封存后迟到读数只记迟到事件。 */
524	    @Transactional
525	    public DailySummaryResponse seal(SealRequest request) {
526	        String fingerprint = FingerprintUtil.sha256(objectMapper, request.requestId(), request);
527	        var existing = idempotentRepository.find(request.requestId());
528	        if (existing != null && existing.requestType().equals("DAILY_SEAL")) {
529	            if (!existing.fingerprint().equals(fingerprint)) {
530	                throw BusinessException.conflict(RejectCategory.IDEMPOTENT_CONFLICT,
531	                        "requestId=" + request.requestId() + " 已用于不同封存参数，拒绝执行");
532	            }
533	            CoFiringPlan plan = existing.planId() == null ? null
534	                    : planRepository.findById(existing.planId());
535	            return buildSummary(plan, request.summaryDate());
536	        }
537	
538	        CoFiringPlan plan = requirePlanByNo(request.planNo());
539	        DailySummaryRepository.DailySummaryRow row =
540	                dailySummaryRepository.find(plan.id(), request.summaryDate());
541	        LocalDateTime now = LocalDateTime.now(clock);
542	        if (row == null || !row.sealed()) {
543	            DailySummaryResponse response = buildSummary(plan, request.summaryDate());
544	            persistSummary(plan, request.summaryDate(), response, true, now);
545	            // 封存为终态：执行中/停用/禁烧方案统一置 SEALED
546	            if (plan.status() != PlanStatus.SEALED) {
547	                planRepository.markSealed(plan.id(), now, request.summaryDate());
548	            }
549	            // 封存即终结当日执行：释放窑占用槽
550	            if (plan.status() == PlanStatus.EXECUTING) {
551	                kilnLockRepository.release(plan.kilnId());
552	            }
553	            plan = planRepository.findById(plan.id());
554	        }
555	        DailySummaryResponse response = buildSummary(plan, request.summaryDate());
556	        idempotentRepository.trySave(request.requestId(), "DAILY_SEAL", fingerprint, 200,
557	                writeJson(response), plan.id());
558	        return response;
559	    }
560	
561	    /**
562	     * 复算日结：逐小时实际生效比例（初值为申报比例，被下发/升级指令命中的小时起按指令时间生效保底线，
563	     * 取最早一条），实际替代率=各生效小时比例的算术平均；超标时段与降掺记录来自评估与指令表。
564	     */
565	    private DailySummaryResponse buildSummary(CoFiringPlan plan, LocalDate date) {
566	        DailySummaryRepository.DailySummaryRow row =
567	                dailySummaryRepository.find(plan.id(), date);
568	        List<HourlyAssessment> assessments = hourlyAssessmentRepository.findByPlanAndDate(plan.id(), date);
569	        List<ReductionCommand> commands = commandRepository.findByPlanAndDate(plan.id(), date);
570	
571	        // 已封存：优先返回封存快照
572	        if (row != null && row.sealed()) {
573	            return new DailySummaryResponse(
574	                    plan.planNo(), date, row.actualSubstitutionRate(),
575	                    readJsonList(row.effectiveHoursJson(), DailySummaryResponse.EffectiveHour.class),
576	                    readJsonList(row.exceededPeriodsJson(), DailySummaryResponse.ExceededPeriod.class),
577	                    readJsonList(row.reductionRecordsJson(), CommandResponse.class),
578	                    true, row.sealedAt());
579	        }
580	
581	        BigDecimal floor = properties.getFloorSubstitutionRate().setScale(RATE_SCALE,
582	                RoundingMode.HALF_UP);
583	        List<DailySummaryResponse.EffectiveHour> effectiveHours = new ArrayList<>();
584	        List<BigDecimal> ratesForAverage = new ArrayList<>();
585	
586	        for (HourlyAssessment a : assessments) {
587	            // 截至该小时已“执行确认”或“超时升级强制降掺”的指令才实际改变生效比例
588	            boolean reduced = commands.stream().anyMatch(c ->
589	                    !c.hourStart().isAfter(a.hourStart())
590	                            && (c.status() == CommandStatus.CONFIRMED
591	                                    || c.status() == CommandStatus.ESCALATED));
592	            BigDecimal effective = reduced ? floor
593	                    : plan.substitutionRate().setScale(RATE_SCALE, RoundingMode.HALF_UP);
594	            effectiveHours.add(new DailySummaryResponse.EffectiveHour(a.hourStart(), effective,
595	                    a.exceeded()));
596	            ratesForAverage.add(effective);
597	        }
598	
599	        BigDecimal actualRate = ratesForAverage.isEmpty()
600	                ? plan.substitutionRate().setScale(RATE_SCALE, RoundingMode.HALF_UP)
601	                : average(ratesForAverage);
602	
603	        List<DailySummaryResponse.ExceededPeriod> exceededPeriods = assessments.stream()
604	                .filter(HourlyAssessment::exceeded)
605	                .map(a -> new DailySummaryResponse.ExceededPeriod(
606	                        a.hourStart(), a.pollutants(), a.noxAvg(), a.so2Avg(), a.dustAvg()))
607	                .toList();
608	        List<CommandResponse> reductionRecords = commands.stream()
609	                .map(c -> toCommandResponse(plan.planNo(), c)).toList();
610	
611	        DailySummaryResponse response = new DailySummaryResponse(
612	                plan.planNo(), date, actualRate, effectiveHours, exceededPeriods,
613	                reductionRecords, false, null);
614	
615	        // 未封存时每次查询均刷新可复算快照
616	        persistSummary(plan, date, response, false, null);
617	        return response;
618	    }
619	
620	    private void persistSummary(CoFiringPlan plan, LocalDate date, DailySummaryResponse response,
621	                                boolean sealed, LocalDateTime sealedAt) {
622	        dailySummaryRepository.upsert(new DailySummaryRepository.DailySummaryRow(
623	                plan.id(), date, response.actualSubstitutionRate(),
624	                writeJson(response.exceededPeriods()),
625	                writeJson(response.reductionRecords()),
626	                writeJson(response.effectiveHours()),
627	                sealed, sealedAt));
628	    }
629	
630	    // ---------------------------------------------------------------------
631	    // 查询视图
632	    // ---------------------------------------------------------------------
633	
634	    @Transactional(readOnly = true)
635	    public PlanStatusResponse status(String planNo) {
636	        return toStatusResponse(requirePlanByNo(planNo));
637	    }
638	
639	    private ReductionCommand resolveCommand(CoFiringPlan plan, String hourStartText,
640	                                            boolean allowTriggeredPick) {
641	        if (hourStartText != null && !hourStartText.isBlank()) {
642	            LocalDateTime hour = LocalDateTime.parse(hourStartText);
643	            ReductionCommand exact = commandRepository.findByPlanAndHour(plan.id(), hour);
644	            if (exact == null) {
645	                throw BusinessException.notFound(
646	                        "方案 " + plan.planNo() + " 在 " + hour + " 无超标降掺指令");
647	            }
648	            return exact;
649	        }
650	        return commandRepository.findAllByPlan(plan.id()).stream()
651	                .filter(c -> allowTriggeredPick
652	                        || c.status() != CommandStatus.TRIGGERED)
653	                .max(Comparator.comparing(ReductionCommand::hourStart))
654	                .orElseThrow(() -> BusinessException.notFound(
655	                        "方案 " + plan.planNo() + " 暂无可操作的降掺指令"));
656	    }
657	
658	    // ---------------------------------------------------------------------
659	    // 换算与装配辅助
660	    // ---------------------------------------------------------------------
661	
662	    private CoFiringPlan requirePlanByNo(String planNo) {
663	        CoFiringPlan plan = planRepository.findByPlanNo(planNo);
664	        if (plan == null) {
665	            throw BusinessException.notFound("方案 " + planNo + " 不存在");
666	        }
667	        return plan;
668	    }
669	
670	    private BigDecimal limit(String pollutant) {
671	        BigDecimal limit = properties.getEmissionLimits().get(pollutant);
672	        if (limit == null) {
673	            throw new IllegalStateException("缺少污染物限值配置: " + pollutant);
674	        }
675	        return limit;
676	    }
677	
678	    /** 恰等于限值判达标：仅严格大于为超标。 */
679	    private boolean exceeds(BigDecimal value, String pollutant) {
680	        return value.compareTo(limit(pollutant)) > 0;
681	    }
682	
683	    private BigDecimal average(List<EmissionReading> list,
684	                               java.util.function.Function<EmissionReading, BigDecimal> getter) {
685	        List<BigDecimal> values = list.stream().map(getter)
686	                .filter(java.util.Objects::nonNull).toList();
687	        return values.isEmpty() ? null : average(values);
688	    }
689	
690	    private BigDecimal average(List<BigDecimal> values) {
691	        BigDecimal sum = values.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
692	        return sum.divide(BigDecimal.valueOf(values.size()), AVG_SCALE, RoundingMode.HALF_UP);
693	    }
694	
695	    private BigDecimal max(BigDecimal a, BigDecimal b) {
696	        if (a == null) {
697	            return b;
698	        }
699	        return a.max(b);
700	    }
701	
702	    private String ratePercent(BigDecimal rate) {
703	        return rate.multiply(BigDecimal.valueOf(100)).stripTrailingZeros().toPlainString();
704	    }
705	
706	    private String generatePlanNo(LocalDateTime now) {
707	        return "PL" + java.time.format.DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS")
708	                .format(now) + String.format("%03d", (int) (Math.random() * 1000));
709	    }
710	
711	    private PlanResultResponse toPlanResult(CoFiringPlan plan, BigDecimal chlorine, BigDecimal sulfur) {
712	        return new PlanResultResponse(
713	                plan.requestId(), plan.id(), plan.planNo(), plan.kilnId(), plan.status().name(),
714	                plan.status() == PlanStatus.APPROVED,
715	                plan.rejectCategory(), plan.rejectReason(),
716	                chlorine, sulfur, plan.submittedAt());
717	    }
718	
719	    private PlanStatusResponse toStatusResponse(CoFiringPlan p) {
720	        return new PlanStatusResponse(p.id(), p.planNo(), p.kilnId(), p.status().name(),
721	                p.substitutionRate(), p.submittedAt(), p.reviewedAt(), p.startedAt(),
722	                p.stoppedAt(), p.bannedAt(), p.sealedAt());
723	    }
724	
725	    private CommandResponse toCommandResponse(String planNo, ReductionCommand c) {
726	        return new CommandResponse(c.id(), planNo, c.hourStart(), c.pollutant(), c.hourAvg(),
727	                c.status().name(), c.targetRate(), c.triggeredAt(), c.issuedAt(),
728	                c.confirmedAt(), c.escalatedAt());
729	    }
730	
731	    private String writeJson(Object value) {
732	        try {
733	            return objectMapper.writeValueAsString(value);
734	        } catch (Exception e) {
735	            throw new IllegalStateException("JSON 序列化失败", e);
736	        }
737	    }
738	
739	    private <T> T readJson(String json, Class<T> type) {
740	        try {
741	            return objectMapper.readValue(json, type);
742	        } catch (Exception e) {
743	            throw new IllegalStateException("JSON 反序列化失败", e);
744	        }
745	    }
746	
747	    private <T> List<T> readJsonList(String json, Class<T> type) {
748	        if (json == null || json.isBlank()) {
749	            return List.of();
750	        }
751	        try {
752	            return objectMapper.readValue(json,
753	                    objectMapper.getTypeFactory().constructCollectionType(List.class, type));
754	        } catch (Exception e) {
755	            throw new IllegalStateException("JSON 反序列化失败", e);
756	        }
757	    }
758	}
