48	        int threads = 8;
49	        ExecutorService pool = Executors.newFixedThreadPool(threads);
50	        CountDownLatch ready = new CountDownLatch(threads);
51	        CountDownLatch start = new CountDownLatch(1);
52	        AtomicInteger accepted = new AtomicInteger();
53	        AtomicInteger rejected = new AtomicInteger();
54	        List<Future<?>> futures = new java.util.ArrayList<>();
55	
56	        for (int i = 0; i < threads; i++) {
57	            String reqId = String.format("REQ-CONC-%03d", i);
58	            futures.add(pool.submit(() -> {
59	                ready.countDown();
60	                start.await();
61	                PlanResultResponse resp = service.submit(overlappingRequest(reqId));
62	                if (resp.accepted()) {
63	                    accepted.incrementAndGet();
64	                } else {
65	                    rejected.incrementAndGet();
66	                }
67	                return null;
68	            }));
69	        }
