121	    public int updateReview(long id, PlanStatus status, String rejectCategory, String rejectReason,
122	                            LocalDateTime reviewedAt) {
123	        return jdbc.update("""
124	                UPDATE co_firing_plan SET status = ?, reject_category = ?, reject_reason = ?,
