CREATE TABLE IF NOT EXISTS warm_up_ticket (
    id               BIGINT AUTO_INCREMENT PRIMARY KEY,
    request_id       VARCHAR(64) NOT NULL,
    ticket_no        VARCHAR(64) NOT NULL,
    kiln_id          VARCHAR(32) NOT NULL,
    curve_version    VARCHAR(32) NOT NULL,
